files.content:
[hidden] { display: none !important; }
:root {
  color-scheme: dark;
  --ink: #f5f3e9;
  --muted: #a9acc6;
  --night: #171b35;
  --panel: #232947;
  --tile: #303859;
  --line: #454d70;
  --mint: #85f0c5;
  --gold: #ffd477;
}
* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 18px;
  display: grid;
  place-items: center;
  background-color: var(--night);
  background-image: radial-gradient(#343a5b 1px, transparent 1px);
  background-size: 22px 22px;
  color: var(--ink);
  font: 16px/1.45 system-ui, sans-serif;
}
.board {
  width: min(100%, 960px);
  padding: clamp(22px, 5vw, 46px);
  border: 2px solid var(--line);
  border-radius: 18px;
  background: var(--panel);
  box-shadow: 0 12px 0 #101329, 0 24px 60px #0c102344;
}
.header { text-align: center; margin-bottom: 30px; }
.eyebrow, .controls h2, footer, .score-total > span {
  color: var(--mint);
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .13em;
}
h1 { margin: 7px 0 5px; font-size: clamp(30px, 6vw, 48px); line-height: 1.1; }
.header p { margin: 0; color: var(--muted); }
.score-area {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 130px;
  gap: 14px;
  align-items: stretch;
}
.frames { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 6px; }
.frame {
  min-width: 0;
  min-height: 110px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--tile);
  text-align: center;
}
.frame.current { outline: 2px solid var(--gold); outline-offset: 1px; }
.frame-number { padding: 4px 1px; border-bottom: 1px solid var(--line); color: var(--muted); font-size: 12px; font-weight: 700; }
.rolls { height: 35px; display: flex; justify-content: center; align-items: center; gap: 2px; }
.roll { min-width: 14px; color: var(--ink); font-size: 13px; font-weight: 800; }
.roll.mark { color: var(--gold); }
.frame-score { padding-top: 5px; border-top: 1px solid var(--line); color: var(--mint); font-size: 20px; font-weight: 800; }
.score-total {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #1c223f;
  text-align: center;
}
.score-total > span { font-size: 12px; }
.score-total output { margin-top: 6px; color: var(--gold); font-size: 38px; font-weight: 900; font-variant-numeric: tabular-nums; }
.controls { margin-top: 34px; text-align: center; }
.controls h2 { margin: 0 0 14px; }
.pins { display: flex; flex-wrap: wrap; justify-content: center; gap: 9px; }
.pins button {
  width: 52px;
  height: 52px;
  border: 2px solid var(--line);
  border-radius: 10px;
  background: var(--tile);
  color: var(--ink);
  font: 800 18px system-ui, sans-serif;
  cursor: pointer;
  transition: transform .12s, border-color .12s, background .12s;
}
.pins button:hover { transform: translateY(-2px); border-color: var(--mint); }
.pins button:active { transform: translateY(1px); background: #202642; }
.pins button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.pins button:disabled { cursor: default; opacity: .4; }
.status { min-height: 24px; margin: 14px 0 0; color: var(--muted); }
footer { display: flex; justify-content: center; align-items: center; gap: 9px; margin-top: 30px; color: var(--muted); font-size: 12px; }
.pixel-dot { width: 9px; height: 9px; background: var(--mint); box-shadow: 4px 0 var(--mint), 0 4px var(--mint), 4px 4px var(--mint); }
.divider { color: var(--gold); }
@media (max-width: 700px) {
  body { padding: 20px 12px; }
  .board { padding: 24px 14px; }
  .score-area { grid-template-columns: 1fr; }
  .frames { gap: 4px; }
  .frame { min-height: 100px; border-radius: 5px; }
  .frame-number { font-size: 11px; }
  .roll { min-width: 10px; font-size: 11px; }
  .frame-score { font-size: 17px; }
  .score-total { min-height: 88px; }
}
@media (max-width: 420px) {
  .frames { gap: 2px; }
  .frame-number { font-size: 10px; }
  .rolls { gap: 0; }
  .roll { min-width: 8px; font-size: 10px; }
  .frame-score { font-size: 15px; }
  .pins { gap: 7px; }
  .pins button { width: 45px; height: 45px; }
}

const framesEl = document.getElementById('frames');
const pinsEl = document.getElementById('pins');
const totalEl = document.getElementById('total');
const statusEl = document.getElementById('status');
const rolls = [];

for (let pins = 0; pins <= 10; pins++) {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = String(pins);
  button.setAttribute('aria-label', `${pins} ${pins === 1 ? 'pin' : 'pins'}`);
  button.addEventListener('click', () => {
    const frame = currentFrame(rolls);
    if (!frame) return;
    const max = maxPins(frame, rolls);
    if (pins > max) return;
    rolls.push(pins);
    render();
  });
  pinsEl.append(button);
}

function currentFrame(values) {
  let index = 0;
  for (let frame = 0; frame < 10; frame++) {
    if (frame < 9) {
      if (values[index] === undefined) return { frame, roll: 1, index };
      if (values[index] === 10) { index++; continue; }
      if (values[index + 1] === undefined) return { frame, roll: 2, index: index + 1 };
      index += 2;
    } else {
      if (values[index] === undefined) return { frame, roll: 1, index };
      if (values[index + 1] === undefined) return { frame, roll: 2, index: index + 1 };
      const first = values[index], second = values[index + 1];
      if ((first === 10 || first + second === 10) && values[index + 2] === undefined)
        return { frame, roll: 3, index: index + 2 };
      return null;
    }
  }
  return null;
}

function maxPins(frame, values) {
  if (frame.frame === 9 && frame.roll === 2 && values[frame.index - 1] === 10) return 10;
  if (frame.frame === 9 && frame.roll === 3) {
    const first = values[frame.index - 2], second = values[frame.index - 1];
    return first === 10 && second !== 10 ? 10 - second : 10;
  }
  if (frame.roll === 2) return 10 - values[frame.index - 1];
  return 10;
}

function frameData(values) {
  const data = [];
  let index = 0, cumulative = 0;
  for (let frame = 0; frame < 10; frame++) {
    const first = values[index];
    let count = frame === 9 ? 3 : 2;
    if (frame < 9 && first === 10) count = 1;
    const frameRolls = values.slice(index, index + count);
    let score;
    if (frame < 9 && first === 10) {
      if (values[index + 2] !== undefined) score = 10 + values[index + 1] + values[index + 2];
    } else if (frame < 9 && values[index + 1] !== undefined) {
      const second = values[index + 1];
      if (first + second === 10) {
        if (values[index + 2] !== undefined) score = 10 + values[index + 2];
      } else score = first + second;
    } else if (frame === 9 && frameRolls.length === 3) score = frameRolls.reduce((sum, value) => sum + value, 0);
    if (score !== undefined) cumulative += score;
    data.push({ frame, index, rolls: frameRolls, score, cumulative: score === undefined ? null : cumulative });
    index += count;
  }
  return data;
}

function marks(frame) {
  const values = frame.rolls;
  return values.map((value, i) => {
    let mark = String(value);
    if (frame.frame < 9) {
      if (i === 0 && value === 10) mark = 'X';
      else if (i === 1 && values[0] + value === 10) mark = '/';
    } else {
      const first = values[0], second = values[1];
      if (i === 0 && value === 10) mark = 'X';
      else if (i === 1 && (first === 10 && value === 10 || first < 10 && first + value === 10)) mark = first < 10 ? '/' : 'X';
      else if (i === 2 && (second === 10 && value === 10 || first < 10 && first + second === 10 && second + value === 10)) mark = first + second === 10 && first < 10 ? '/' : 'X';
    }
    return mark;
  });
}

function render() {
  const data = frameData(rolls);
  const active = currentFrame(rolls);
  framesEl.replaceChildren();
  data.forEach((item) => {
    const card = document.createElement('div');
    card.className = `frame${active?.frame === item.frame ? ' current' : ''}`;
    card.setAttribute('aria-label', `Frame ${item.frame + 1}`);
    const number = document.createElement('div');
    number.className = 'frame-number';
    number.textContent = String(item.frame + 1).padStart(2, '0');
    const rollRow = document.createElement('div');
    rollRow.className = 'rolls';
    marks(item).forEach((mark) => {
      const cell = document.createElement('span');
      cell.className = `roll${mark === 'X' || mark === '/' ? ' mark' : ''}`;
      cell.textContent = mark;
      rollRow.append(cell);
    });
    const score = document.createElement('div');
    score.className = 'frame-score';
    score.textContent = item.cumulative === null ? '—' : String(item.cumulative);
    card.append(number, rollRow, score);
    framesEl.append(card);
  });
  totalEl.textContent = active ? '—' : String(data[9].cumulative ?? 0);
  if (active) {
    const label = `Frame ${active.frame + 1} · Roll ${active.roll}`;
    statusEl.textContent = label;
    pinsEl.querySelectorAll('button').forEach((button) => {
      button.disabled = Number(button.textContent) > maxPins(active, rolls);
    });
  } else {
    statusEl.textContent = 'Game complete · final score recorded';
    pinsEl.querySelectorAll('button').forEach((button) => { button.disabled = true; });
  }
}

render();
